        public class FeatureRule
        {
            public FeatureRule(int feature, long offset, uint bits)
            {
                Feature = feature;
                Offset = offset;
                Bits = bits;
            }

            public int Feature { get; }
            public long Offset { get; }
            public uint Bits { get; }
        }

        public class PeripheralRule
        {
            public PeripheralRule(long offset, uint bits, int gtzc, int configurationRegister, int bit, string[] peripherals)
            {
                Offset = offset;
                Bits = bits;
                Gtzc = gtzc;
                ConfigurationRegister = configurationRegister;
                Bit = bit;
                TrustZoneAwarePeripherals = peripherals;
            }

            public long Offset { get; }
            public uint Bits { get; }
            // GTZC instance (1 or 2) of a securable peripheral, 0 for a TrustZone-aware one.
            public int Gtzc { get; }
            public int ConfigurationRegister { get; }
            public int Bit { get; }
            public string[] TrustZoneAwarePeripherals { get; }
        }
    }
